/bin/bash -lc "node - <<'NODE'
const map=require('./requirements/.rename_map.json');
const {execSync}=require('child_process');
const entries=Object.entries(map)
  .filter(([k,v]) => "'!['"'axis-log-small-ticks.yaml','build-check-test-revert.yaml','husky-checkheader-removal.yaml','visualmap-range-comparison.yaml'].includes(v))
  .map(([k,v])=>({num:k.replace('.yaml',''),slug:v.replace('.yaml','')}));
for (const {num,slug} of entries) {
  let out='';
  try {
    out=execSync("'`git log --all --decorate=short --oneline --grep='"'(#"'${num})'"' --grep='"'${num}'"' --max-count=8"'`, {encoding:'"'utf8'}).trim();
  } catch (e) {
    out=(e.stdout||'').trim();
  }
  console.log('### '+slug+' '+num);
  console.log(out || '(no direct grep match)');
}
NODE"

