/bin/bash -lc "node - <<'NODE'
const map=require('./requirements/.rename_map.json');
const skip=new Set(['axis-log-small-ticks.yaml','build-check-test-revert.yaml','husky-checkheader-removal.yaml','visualmap-range-comparison.yaml']);
const {execSync}=require('child_process');
function run(cmd){try{return execSync(cmd,{encoding:'utf8'}).trim();}catch(e){return (e.stdout||'').trim();}}
for (const [k,v] of Object.entries(map)) {
  if (skip.has(v)) continue;
  const num=k.replace('.yaml','');
  const slug=v.replace('.yaml','');
  const merge=run("'`git log --all --oneline --grep='"'(#"'${num})'"' --grep='"'${num}'"' --max-count=1"'`);
  console.log('"'###',slug,num);
  console.log('match:', merge || '(none)');
  const hash=merge.split(' ')[0];
  if (hash && /"'^[0-9a-f]{7,}$/.test(hash)) {
    const parents=run(`git rev-list --parents -n 1 ${hash}`).split('"' ');
    if (parents.length===3) {
      const inner=run("'`git rev-list --reverse ${hash}''^1..${hash}''^2 | while read c; do git show -s --format='"'%h %s' "'$c; done`);
      console.log('"'inner:', inner || '(none)');
    }
    else {
      console.log('inner: n/a');
    }
  }
}
NODE"

